@startuml

class Song {
  + Title : string
  + Year : int
  + Length : int
  + Genre : string
}

class Artist {
  + Name : string
  + BirthDate : date
  + WebsiteURL : string
}

class User {
  + UserID : int
  + Name : string
  + Address : string
}

class BusinessUser extends User {
  + VATNumber : string
}

class RegularUser extends User {}

class Single extends Song {}

class Hit extends Song {}

class Album {
  + TrackNumber : int
}

Artist "1" -- "*" Song
BusinessUser "1" -- "*" Song : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "*" -- "1..*" Hit : contains

@enduml

